# src/domain/state.py
from typing import TypedDict, Annotated
import operator
from src.domain.animation import AnimationSpec
from src.domain.models import ExerciseModel
from src.resolution.variants import ExerciseVariant

class GraphState(TypedDict):
    # Input
    raw_exercise_name: str
    variant: ExerciseVariant | None  # the exact variant picked in the CLI (None = free-text name)
    
    # Payload generated by the LLM
    structured_exercise: ExerciseModel | None
    
    # Animation spec generated by the LLM and rendered with Manim
    animation_spec: AnimationSpec | None
    spec_attempts: int

    
    # Flow control and self-healing
    validation_errors: Annotated[list[str], operator.add]
    generation_attempts: int